import "./index.less"
import { countryList, } from '@utils/staticData'
import { addStoriesRecruit, } from '@utils/api.js'


class RenderCountry {
    constructor({ el, }) {
        this.DOM = document.querySelector(el)

        this.countryWrap = document.querySelector('[data-country-wrap]')
        this.countryInput = document.querySelector('[data-country-input]')

        this.phoneWrap = document.querySelector('[data-phone-wrap]')
        this.flag = document.querySelector('[data-phone-flag]')
        this.country = document.querySelector('[data-phone-country]')
        this.arrow = document.querySelector('[data-phone-arrow]')
        this.prefix = document.querySelector('[data-phone-prefix]')

        this.countryItems = []

        this.init(countryList)

        this.handleInputFilter = this.handleInputFilter.bind(this)
        this.countryInput.addEventListener('input', this.handleInputFilter, false)

        window.addEventListener('scroll', () => this.countryWrap.parentElement.classList.remove('active'), false)

        // 监听整个文档的点击事件
        this.handleClickOutside = this.handleClickOutside.bind(this)
        document.addEventListener('click', this.handleClickOutside)
    }
    init(list) {
        const html = this.renderDOM(list)
        this.DOM.innerHTML = html

        this.countryItems = document.querySelectorAll('[data-country-item]')
        this.countryItems.forEach(it => it.onclick = () => this.handleClickItem(it))
    }
    renderDOM(list) {
        let html = ''
        list.forEach(({ country, iso, code, }) => {
            html += `
                <li
                    class="
                        text-black Poppins-Regular font-normal
                        text-26 px-16 py-14 mb-8 rounded-16
                        lg:j-text-13 lg:j-px-8 lg:j-py-7 lg:j-mb-4 lg:j-rounded-8
                        xl:a-text-13 xl:a-px-8 xl:a-py-7 xl:a-mb-4 xl:a-rounded-8
                        hover:bg-#FEFEFE
                    "
                    data-iso="${iso}"
                    data-code="${code}"
                    data-country="${country}"
                    data-country-item
                >${country}</li>
            `
        })

        return html || `
            <div
                class="
                    w-full text-center text-#999
                    text-26 leading-72
                    lg:j-text-13 lg:j-leading-36
                    xl:a-text-13 xl:a-leading-36
                "
            >Country Not Matched</div>
        `
    }
    handleClickItem(it) {
        this.countryItems.forEach(it => it.classList.remove('country-item-active'))
        it.classList.add('country-item-active')

        const { iso, code, country, } = it.dataset
        this.flag.setAttribute(
            'src',
            `https://cdn.shopify.com/static/images/flags/${iso.toLowerCase()}.svg?width=45`
        )
        this.country.innerHTML = iso
        this.prefix.innerHTML = code

        this.countryWrap.dataset.country = country
        this.countryWrap.dataset.code = code
        this.countryWrap.dataset.iso = iso

        this.countryWrap.parentElement.classList.toggle('active')
    }
    handleInputFilter(e) {
        const value = e.target.value
        const list = countryList.filter(it => it.country.includes(value))

        this.init(list)
    }
    handleClickOutside(e) {
        // 检查点击事件的目标是否位于目标元素内部
        if (!this.countryWrap.contains(e.target) && !this.phoneWrap.contains(e.target)) {
            this.countryWrap.parentElement.classList.remove('active')
        }
    }
}

class SelectCountry {
    constructor() {
        this.countryWrap = document.querySelector('[data-country-wrap]')

        this.phoneWrap = document.querySelector('[data-phone-wrap]')

        this.flag = document.querySelector('[data-phone-flag]')
        this.country = document.querySelector('[data-phone-country]')
        this.arrow = document.querySelector('[data-phone-arrow]')
        this.prefix = document.querySelector('[data-phone-prefix]')

        this.handleClick = this.handleClick.bind(this)

        this.init()
    }
    init() {
        this.phoneWrap.addEventListener('click', this.handleClick, false)
    }
    handleClick() {
        this.countryWrap.parentElement.classList.toggle('active')
    }
}

class FormSubmitValidator {
    constructor({ required, email, submitBtn, }) {
        this.requiredArray = required.map(({ targetEl, errorEl, }) => ({
            target: this.$$(targetEl),
            error: this.$$(errorEl),
        }))
        this.emailArray = email.map(({ targetEl, errorEl, }) => ({
            target: this.$$(targetEl),
            error: this.$$(errorEl),
        }))


        this.isSubmitted = false // 表单是否已经提交标识
        this.submitBtn = this.$$(submitBtn)


        this.form = {
            firstName: '',
            lastName: '',
            email: '',
            phoneCountry: '',
            phoneNumber: '',
            profession: '',
            haveProduct: '',
            userProduct: '',
            scenarios: '',
            joinFlag: 0,
        }

        this.agreeDOM = this.$$('[data-agree]')

        this.agreeDOM.addEventListener('change', (e) => {
            if (e.target.checked) {
                this.submitBtn.removeAttribute('disabled')
            } else {
                this.submitBtn.setAttribute('disabled', true)
            }
        })

        this.submitBtn.onclick = (e) => this.handleSubmit(e)
    }
    $$(entity) {
        return entity ? document.querySelector(entity) : null
    }
    validateForm() {
        const rules = {
            required: true,
        }
        const emailRules = {
            required: true,
            email: true,
        }

        let valid = false

        this.requiredArray.forEach(({ target, error, }) => {
            if (target) {
                const result = approve.value(target.value.trim(), rules);
                if (result.approved) {
                    valid = true
                    error.classList.add('hidden')
                } else {
                    valid = false
                    error.classList.remove('hidden')
                }
            }
        })

        this.emailArray.forEach(({ target, error, }) => {
            if (target) {
                const result = approve.value(target.value.trim(), emailRules);
                if (result.approved) {
                    valid = true
                    error.classList.add('hidden')
                } else {
                    valid = false

                    if (window.pageInfo?.cr === 'DE') {
                        error.innerHTML = target.value.trim() === ''
                            ? 'Dieses Feld ist erforderlich'
                            : 'Dieses Feld muss eine gültige E-Mail-Adresse sein'
                    } else {
                        error.innerHTML = `This field ${result.errors[0]}`
                    }
                    
                    error.classList.remove('hidden')
                }
            }
        })

        return valid
    }
    async handleSubmit(e) {
        // 阻止默认表单事件提交
        e.preventDefault()

        const valid = this.validateForm()
        if (valid) {
            
            if (!this.isSubmitted) {
                this.isSubmitted = true

                const countryWrap = document.querySelector('[data-country-wrap]')
                const { iso, code, country: phoneCountry, } = countryWrap.dataset

                this.form.firstName = this.$$('[data-first-name]').value
                this.form.lastName = this.$$('[data-last-name]').value
                this.form.email = this.$$('[data-email]').value
                this.form.phoneNumber = this.$$('[data-phone-number]').value
                this.form.profession = this.$$('[data-profession]').value
                this.form.userProduct = this.$$('[data-product-use]').value
                this.form.scenarios = this.$$('[data-product-for]').value
                this.form.joinFlag = this.agreeDOM.checked ? 1 : 0
                this.form.phoneCountry = phoneCountry

                const { data, } = await addStoriesRecruit({ ...this.form, })
                const message = window.pageInfo?.cr === 'DE' ? 'Eingereicht!' : 'You application has been recieved!'
                if (data) {
                    pushSuccessMessage(message, 5000)

                    const targets = this.requiredArray.map(it => it.target)
                    targets.forEach(it => it.value = '')
                    this.$$('[data-email]').value = ''
                    this.$$('[data-phone-number]').value = ''
                    this.agreeDOM.checked = false

                    this.submitBtn.setAttribute('disabled', true)
                } else {
                    pushErrorMessage(message, 5000)
                }

                this.isSubmitted = false
            }
            
        }
    }
}

document.addEventListener('DOMContentLoaded', () => {

    new RenderCountry({
        el: '[data-country-list]',
    })
    new SelectCountry()

    new FormSubmitValidator({
        required: [
            {
                targetEl: '[data-first-name]',
                errorEl: '[data-first-name-error]',
            },
            {
                targetEl: '[data-last-name]',
                errorEl: '[data-last-name-error]',
            },
            {
                targetEl: '[data-profession]',
                errorEl: '[data-profession-error]',
            },
            {
                targetEl: '[data-product-use]',
                errorEl: '[data-product-use-error]',
            },
            {
                targetEl: '[data-product-for]',
                errorEl: '[data-product-for-error]',
            }
        ],
        email: [
            {
                targetEl: '[data-email]',
                errorEl: '[data-email-error]',
            }
        ],
        submitBtn: '[submit-to-join]',
        submitCallback: (data) => {
            console.log(data)
        }
    })
})
